#!/usr/bin/env bash
# KaSe brick: the rf-scope host tool's pure tests (tools/rf_scope/tests,
# pytest). They decode docs/contracts/rf_trace_vectors.json — generated by
# the firmware's rf_trace.c and pinned on the C side by test_rf_trace — so a
# change of the trace format that forgets the Python codec turns red here.
# Runs when python3 can import pytest; otherwise SKIPPED WITH A NOTICE (the
# system python has no pytest — run it by hand with the nix command below).
# No cache directory is written (it would change check.sh's fingerprint).
# Sourced by scripts/check.sh.
check_rf_scope_pytest() {
  [ -d tools/rf_scope/tests ] || return 0
  if ! python3 -c 'import pytest' >/dev/null 2>&1; then
    info "rf_scope pytest SKIPPED (no pytest for python3) — run: nix shell --impure --expr 'with import <nixpkgs> {}; python3.withPackages (p: [p.pytest p.pyserial])' --command python3 -m pytest tools/rf_scope/tests -q"
    return 0
  fi
  local out
  if ! out="$(PYTHONDONTWRITEBYTECODE=1 python3 -m pytest -q -p no:cacheprovider tools/rf_scope/tests 2>&1)"; then
    printf '%s\n' "$out" | tail -25 >&2
    fail "rf_scope pytest: red — detail: python3 -m pytest tools/rf_scope/tests"
    return 1
  fi
  ok "rf_scope pytest ($(printf '%s\n' "$out" | tail -1))"
  return 0
}
TW_PRE_FAST+=(check_rf_scope_pytest)
